 const collectiveEntrance='<nav class="collective-switch" aria-label="'+(museumLang==='en'?'Historical collection sections':museumConvert('历史展厅分馆'))+'"><a class="is-active" href="#/history">'+(museumLang==='en'?'Personal Archives':museumConvert('个人档案'))+'</a><a href="#/collectives">'+(museumLang==='en'?'Collective Archives':museumConvert('群体档案'))+'</a></nav><p class="collective-entrance-note">'+(museumLang==='en'?'Explore individual decisions here, or enter the Collective Archives to examine how law, work and social hierarchies shaped who could be heard.':museumConvert('在这里阅读一个人如何决定话语的去向；也可以进入群体档案，追问法律、劳动与社会秩序怎样决定谁能够被听见。'))+'</p>';
 const unsentLenses=[
  ["The Undelivered","未曾抵达","Words with an intended recipient who never received them.","那些原本有收信人，却终究未曾抵达的话。"],
  ["The Withheld","被留在身后的文字","Manuscripts or thoughts deliberately kept from publication.","手稿已经写成，作者却为它关上了公开的门。"],
  ["The Unnamed","没有署名的声音","Works made public while the writer's identity remained private.","作品走向人群，作者的姓名仍被留在书页之外。"],
  ["The Silenced","被迫中断的声音","Expression constrained by law, coercion, threats or force.","法律、威胁与强制权力，让原本能够说的话被迫停下。"],
  ["The Unheard","无人倾听的声音","Words expressed but denied a meaningful response.","有人其实早已开口，却始终没有获得应有的回应。"],
  ["The Unrepresented","未能留在档案里的人们","Lives underrepresented because of unequal access to writing and records.","不是没有经历，而是缺少把经历写下并留给后世的机会。"]
 ];
